library(readr)
library(curl)
url_scada <- "https://raw.githubusercontent.com/uriel278/tutorials-cp/main/data/scada.csv"
ds_scada <- read_csv(curl(url_scada))
head(ds_scada)
d_scada <- data.frame(y = ds_scada$active_power, x = ds_scada$wind_speed)


## ----splits-data, echo=TRUE---------------------------------------------------
set.seed(141019)
idx <- sample(x = c("train", "calib", "test"), prob = c(0.6, 0.252, 0.148),
  size = nrow(d_scada), replace = TRUE)
scada <- split(d_scada, idx)


## ----plot-splits, layout = "l-page", echo=TRUE, fig.show = "hold", fig.dim=c(12, 4), fig.width = "100%", out.width="100%", fig.cap = "Splits of the original dataset. Left: Proper training data to fit each model. Middle: Proper calibration data for computation of nonconformity scores. Right: Test split to evaluate empirical coverage of each prediction interval."----
cols <- c(
  palette.colors(3, palette = "Paired"),
  palette.colors(2, palette = "Okabe-Ito")
)
par(mfrow = c(1, 3))
with(scada, {
  plot(y ~ x, data = train,
     col = cols[1], xlab = "x", ylab = "y", main = "Training", pch = 20)
plot(y ~ x, data = calib,
     col = cols[2], xlab = "x", ylab = "y", main = "Calibration", pch = 20)
plot(y ~ x, data = test,
     col = cols[3], xlab = "x", ylab = "y", main = "Testing", pch = 20)
})


## ----baseR-lm, echo=TRUE, warning=FALSE, message=FALSE------------------------
linear_model <- lm(y ~ x + I(x^2), data = scada$train)


## ----reg-scam, echo=TRUE, message=FALSE, warning=FALSE------------------------
library(scam)
scam_model <- scam(y ~ s(x, bs = "mpi"), family = Gamma(link = "identity"),
                   data = scada$train)


## ----rf-model-spec, echo=TRUE, warning=FALSE, message=FALSE-------------------
library(tidymodels)
library(parsnip)
rf_spec <- rand_forest(trees = 154, min_n = 813) %>%
  set_engine("ranger", importance = "impurity") %>%
  set_mode("regression")
rf_wf <- workflow() %>%
  add_model(rf_spec) %>%
  add_formula(y ~ x)
rf_fit <- rf_wf %>% fit(data = scada$train)


