## ----load-data-ts, message=FALSE, echo=TRUE-----------------------------------
library(readr)
library(curl)
url_dengue <- "https://raw.githubusercontent.com/uriel278/tutorials-cp/main/data/dengue.csv"
d_dengue <- read_csv(curl(url_dengue))
d_dengue <- ts(d_dengue$x, start = c(2010, 1), frequency = 52)
summary(d_dengue)


## ----dengue-ts-time-split, echo=TRUE------------------------------------------
dtrain_dengue <- window(d_dengue, start = c(2010, 1), end = c(2013, 52))
dcal_dengue <- window(d_dengue, start = c(2014, 1), end = c(2017, 52))
dtest_dengue <- window(d_dengue, start = c(2018, 1))


## ----plot-ts-splits, layout = "l-page", fig.show = "hold", fig.dim=c(8, 4), fig.width = "100%", out.width="100%", fig.cap = "Splits of the dengue time series for the example. The initial training split (in light blue), calibration set (in dark blue) and the testing set in dashed green lines.", echo=FALSE----
cols <- c(
  palette.colors(3, palette = "Paired"),
  palette.colors(2, palette = "Okabe-Ito")
)
plot(d_dengue*NA, ylim = c(0, 12500), ylab = "# Cases")
lines(dtrain_dengue, col = cols[1], lwd = 2)
lines(dcal_dengue, col = cols[2], lwd = 2)
lines(dtest_dengue, col = cols[3], lwd = 2, lty = 5)
legend('topright', legend=c('Initial training','Calibration', 'Testing'),
       col = cols, lty = c(1, 1, 3), lwd = 2)


